-- ============================================================================\n-- Personalized task refresh rate-limit column.\n-- ============================================================================\n-- Added so the server can enforce a cooldown between personalized-task\n-- refreshes without reusing noisy columns (updated_at is touched by profile\n-- saves, assessment saves, etc.).\n-- ============================================================================\n\nALTER TABLE public.user_personalization\n  ADD COLUMN IF NOT EXISTS last_personalized_refresh_at timestamptz;\n